<?php $page_title = 'Your cart'; require __DIR__ . '/../partials/shop_open.php'; $cart = $cart ?? []; $total = array_sum(array_map(static function ($item) { return (float)$item['price'] * (float)$item['qty']; }, $cart)); ?>
<main id="main" class="inner-page shell"><div class="page-intro"><p class="eyebrow">GOOD CHOICES, ALL AROUND</p><h1>Your next good meal.</h1><p>A little of what you love. Review your picks below.</p></div>
<?php if (!$cart): ?><div class="menu-empty"><span aria-hidden="true">✳</span><h2>Your cart is waiting.</h2><p>Find something you love and add it to your order.</p><a class="button button-red" href="<?= url('?route=products') ?>">Find your favorite ↗</a></div><?php else: ?><div class="cart-layout"><section class="cart-items" aria-label="Cart items"><?php foreach ($cart as $item): ?><article class="cart-item"><a href="<?= url('?route=product_detail&id='.(int)$item['id']) ?>"><img src="<?= $escape(get_product_image($item['image_url'] ?? '', $item['id'])) ?>" alt="<?= $escape($item['name']) ?>" width="240" height="240"></a><div class="cart-item-info"><p class="product-category"><?= $escape($item['category_name'] ?? 'On the menu') ?></p><h2><a href="<?= url('?route=product_detail&id='.(int)$item['id']) ?>"><?= $escape($item['name']) ?></a></h2><p class="muted"><?= $escape($currency) ?><?= number_format((float)$item['price'], 2) ?> each</p><div class="cart-item-actions"><form class="quantity-picker" action="<?= url('?route=cart/update') ?>" method="post"><input type="hidden" name="csrf_token" value="<?= $escape(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><button type="submit" name="qty" value="<?= max(0, $item['qty'] - 1) ?>" aria-label="Decrease <?= $escape($item['name']) ?> quantity">−</button><span aria-label="Quantity"><?= (int)$item['qty'] ?></span><button type="submit" name="qty" value="<?= min((int)$item['stock'], $item['qty'] + 1) ?>" <?= $item['qty'] >= $item['stock'] ? 'disabled' : '' ?> aria-label="Increase <?= $escape($item['name']) ?> quantity">+</button></form><form action="<?= url('?route=cart/remove') ?>" method="post"><input type="hidden" name="csrf_token" value="<?= $escape(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><button class="remove-item" type="submit">Remove</button></form></div></div><strong class="cart-line-total"><?= $escape($currency) ?><?= number_format($item['price'] * $item['qty'], 2) ?></strong></article><?php endforeach; ?><a class="text-link" href="<?= url('?route=products') ?>">← Add something else</a></section>
<aside class="shop-panel cart-summary"><p class="eyebrow">THE GOOD STUFF, TOGETHER</p><h2>Your order.</h2><div class="order-total"><span>Subtotal</span><strong><?= $escape($currency) ?><?= number_format($total, 2) ?></strong></div><div class="order-total grand-total"><span>Total</span><strong><?= $escape($currency) ?><?= number_format($total, 2) ?></strong></div><p class="body-copy">Choose your pickup branch and check availability. Place your order now and pay when you collect it.</p>
<form class="shop-form" action="<?= url('') ?>" method="get"><input type="hidden" name="route" value="cart"><label for="pickup-branch">Pickup branch<select id="pickup-branch" name="branch_id" required><option value="">Choose a branch</option><?php foreach ($branches ?? [] as $branch): ?><option value="<?= (int)$branch['id'] ?>" <?= (int)($selected_branch ?? 0)===(int)$branch['id']?'selected':'' ?>><?= $escape($branch['name']) ?></option><?php endforeach; ?></select></label><button type="submit" class="button button-outline">Check availability ↗</button></form>
<?php $shortage=false; foreach ($cart as $line) { if($line['qty']>$line['stock']) $shortage=true; } ?>
<?php if($shortage): ?><p class="order-warning" role="alert">Some quantities are unavailable at this branch. Reduce the quantities or choose another branch.</p><?php endif; ?>
<?php if(empty($_SESSION['user'])): ?><p class="body-copy">Sign in to place and track your order. Your cart will be kept.</p><a class="button button-red" href="<?= url('?route=login') ?>">Sign in to order ↗</a><?php else: ?>
<?php if(!OnlineOrder::enabled()): ?><p class="order-warning" role="status">Online ordering is currently closed. You can still track your existing orders.</p><?php endif; ?>
<form class="shop-form" method="post" action="<?= url('?route=cart/checkout') ?>" data-online-checkout><input type="hidden" name="csrf_token" value="<?= $escape(csrf_token()) ?>"><input type="hidden" name="cart_quote" value="<?= $escape(Cart::fingerprint($cart,$selected_branch ?? null)) ?>"><input type="hidden" name="expected_total" value="<?= number_format($total,2,'.','') ?>"><input type="hidden" name="request_key" value="<?= $escape($_SESSION['online_checkout_key'] ?? '') ?>"><input type="hidden" name="branch_id" value="<?= (int)($selected_branch ?? 0) ?>"><label for="order-payment">Payment method<select id="order-payment" name="payment_method"><option value="pay_at_counter">Pay at counter</option></select></label><label for="order-name">Your name<input id="order-name" name="name" required maxlength="150" autocomplete="name" value="<?= $escape($_SESSION['user']['name'] ?? '') ?>"></label><label for="order-email">Email address<input id="order-email" name="email" type="email" required maxlength="254" autocomplete="email" value="<?= $escape($_SESSION['user']['email'] ?? '') ?>"></label><label for="order-phone">Contact number<input id="order-phone" name="phone" type="tel" required minlength="7" maxlength="40" autocomplete="tel" placeholder="Your mobile number"></label><button class="button button-red" type="submit" <?= empty($selected_branch)||$shortage||!OnlineOrder::enabled()?'disabled':'' ?>>Place order ↗</button></form><?php endif; ?></aside></div><?php endif; ?></main>
<?php require __DIR__ . '/../partials/shop_close.php'; ?>
